// Construye un objeto `response` conforme a Open Responses.
// Ticket #1: sin autenticacion y sin agente. Solo fija la forma de la salida.

const body = $json.body ?? {};

// `crypto` no existe en el sandbox del task runner de n8n.
// El id solo tiene que ser opaco y unico, no criptografico.
const id = (prefijo) =>
  prefijo + '_' + Date.now().toString(36) + Math.random().toString(36).slice(2, 12);

// ponytail: el ticket #1 solo exige `input` como string.
// El array de items lo cubre el ticket #3.
const texto = typeof body.input === 'string' ? body.input : '';

return [{
  json: {
    id: id('resp'),
    object: 'response',
    created_at: Math.floor(Date.now() / 1000),
    status: 'completed',
    model: body.model ?? 'bano',
    output: [
      {
        id: id('msg'),
        type: 'message',
        status: 'completed',
        role: 'assistant',
        content: [
          {
            type: 'output_text',
            text: 'eco: ' + texto,
            annotations: [],
          },
        ],
      },
    ],
    usage: { input_tokens: 0, output_tokens: 0, total_tokens: 0 },
  },
}];
